def solve(n):
    MOD = 1000000007

    # For each possible sum s = i + j where 0 <= i, j < n
    # We need s to be prime and s in range [0, 2*n-2]

    max_sum = 2 * n - 2
    if max_sum < 2:
        return 0

    # Count how many times each prime sum appears
    total_cells = 0

    # For each prime sum s, count how many valid (i,j) pairs satisfy i+j = s
    # where 0 <= i, j < n
    # i ranges from max(0, s-n) to min(s, n-1)
    # number of valid pairs = min(s, n-1) - max(0, s-n) + 1, if valid
    # But only if s is prime

    for s in range(2, max_sum + 1):
        if is_prime(s):
            # Count valid pairs (i,j) such that i+j = s and 0 <= i,j < n
            i_min = max(0, s - (n - 1))  # j = s - i < n => i > s - n
            i_max = min(s, n - 1)       # i < n and i <= s

            if i_min <= i_max:
                count_pairs = i_max - i_min + 1
                total_cells = (total_cells + count_pairs) % MOD

    return total_cells

